1	/**
2	 * path-patterns.ts — the one path-pattern form Atomaton's configuration accepts.
3	 *
4	 * A pattern is a literal path, or a directory followed by `/**`. That is all.
5	 * Deliberately not a glob library, and the reason is not laziness: a
6	 * half-implemented glob is read as a full one. Someone writes `**\/*.sql`,
7	 * matches nothing, and their gate silently never fires -- which is worse than no
8	 * gate at all, because they believe they have one.
9	 *
10	 * So the form is small AND checked. `pathPatternProblem` rejects anything this
11	 * matcher cannot honour, and both callers -- `merge.gates` and
12	 * `merge.governed_paths` -- report that as a configuration problem rather than
13	 * matching zero files and carrying on. A pattern that cannot work says so at the
14	 * moment it is read.
15	 *
16	 * `merge.governed_paths` was not checked for a while, and the header here claimed it
17	 * was. That is the worse half of the same mistake: a gate over the agent's own
18	 * limits, silently matching nothing, under a comment saying it could not.
19	 *
20	 * Extracted from `merge-readiness.ts`, where `governedPathsIn` had the matcher
21	 * inline. `merge.gates` needed the same one, and two copies of a security-shaped
22	 * comparison is exactly the arrangement that drifts.
23	 */
24	
25	/** Whether `pattern` claims `file`. */
26	export function pathMatches(file: string, pattern: string): boolean {
27	  return pattern.endsWith("/**") ? file.startsWith(pattern.slice(0, -2)) : file === pattern;
28	}
29	
30	/**
31	 * Why `pattern` is not one `pathMatches` can honour, or "" when it is fine.
32	 *
33	 * The wildcard check is the point. A trailing `/**` is the supported form; a `*`
34	 * anywhere else -- `**\/*.sql`, `db/*\/migrations/**`, `*.ts` -- would be compared
35	 * literally and match nothing.
36	 */
37	const GLOB_CHARACTERS = /[*?[\]{}]/;
38	
39	export function pathPatternProblem(pattern: string): string {
40	  if (typeof pattern !== "string" || pattern.trim() === "") {
41	    return "a path pattern must be a non-empty string";
42	  }
43	  if (pattern !== pattern.trim()) {
44	    return `"${pattern}" has surrounding whitespace`;
45	  }
46	
47	  // A trailing slash is the ordinary way a person writes a directory, and it is
48	  // the one spelling that looks right and claims nothing: `pathMatches` sees no
49	  // `/**`, falls through to the literal comparison, and no file is ever named
50	  // with a trailing slash. Caught before the glob check so the message can name
51	  // the fix rather than the character.
52	  if (pattern.endsWith("/")) {
53	    return (
54	      `"${pattern}" ends in a slash, so it would match nothing. ` +
55	      `Write "${pattern}**" for everything under it, or drop the slash to match that one path.`
56	    );
57	  }
58	
59	  // Everything except a trailing `/**` is compared literally, so any other glob
60	  // character is a pattern that reads as a glob and behaves as a filename. A
61	  // literal path containing one of these is refused too: it could in principle
62	  // be matched, but telling the two apart needs intent this cannot see, and a
63	  // refusal a person fixes beats a gate that quietly never fires.
64	  const body = pattern.endsWith("/**") ? pattern.slice(0, -3) : pattern;
65	  if (body === "") {
66	    return `"${pattern}" names no directory. Write the directory before the "/**".`;
67	  }
68	  const glob = GLOB_CHARACTERS.exec(body);
69	  if (glob) {
70	    return (
71	      `"${pattern}" uses the glob character '${glob[0]}', which this matcher cannot honour, ` +
72	      'so it would match nothing. Write a literal path, or a directory followed by "/**".'
73	    );
74	  }
75	  return "";
76	}

