1	#!/usr/bin/env bun
2	/**
3	 * inject_dispatcher_notice.ts — Append a "who started this run" notice to the
4	 * agent's session.json messages array, so the run knows who is waiting on its
5	 * result and reports back to them.
6	 *
7	 * Usage: inject_dispatcher_notice.ts --session <path> --dispatched-by <agent>
8	 *
9	 * ## Why this is a user message and not a template placeholder
10	 *
11	 * The system prompt is built by the atoma core from a fixed set of placeholders
12	 * (`{{AGENT_NAME}}`, `{{COLLEAGUES_LIST}}`, ...), and adding one is a change to
13	 * the core's own vocabulary -- a change to what `atoma` takes as an argument. The
14	 * fact here is not the core's: who started a run is a fact about this delivery
15	 * system, and the delivery system already has a way to put a fact in front of the
16	 * agent -- a `role: "user"` message in the session, which is exactly what
17	 * `inject_uncommitted_notice.ts` does for the same reason.
18	 *
19	 * ## Why the run cannot work this out for itself
20	 *
21	 * The dispatch comment on the sub-issue names the agent being STARTED, never the
22	 * one starting it, and the sub-issue body carries no such field. So an engineer
23	 * dispatched by an atomaton had no way to tell that an atomaton was waiting, and
24	 * ended with a plain comment on its own sub-issue instead of reporting back. The
25	 * name travels as `ATOMATON_DISPATCHED_BY` (see `RunnerDispatch.dispatchedBy`),
26	 * and this puts it where the model reads it.
27	 *
28	 * Empty when a person or the machinery started the run: there is no agent to
29	 * report to, and the notice says so rather than inventing one.
30	 */
31	import { existsSync, readFileSync, writeFileSync } from "node:fs";
32	import { parseArgs } from "node:util";
33	import { defineScript } from "./lib/script-ref.ts";
34	import type { Session } from "../../domain/work/session.ts";
35	
36	export interface InjectDispatcherNoticeArgs {
37	  session: string;
38	  "dispatched-by": string;
39	}
40	
41	export const ref = defineScript<InjectDispatcherNoticeArgs>(import.meta.url);
42	
43	function main(): void {
44	  const { values } = parseArgs({
45	    args: Bun.argv.slice(2),
46	    options: { session: { type: "string" }, "dispatched-by": { type: "string" } },
47	  });
48	  const path = values.session;
49	  if (!path) {
50	    console.error("usage: inject_dispatcher_notice.ts --session <path> --dispatched-by <agent>");
51	    process.exit(2);
52	  }
53	  const dispatchedBy = (values["dispatched-by"] ?? "").trim();
54	  if (!dispatchedBy) {
55	    // A person or the machinery started this run. There is nobody to report to,
56	    // and saying nothing is the honest answer -- the prompt's own handoff rules
57	    // already cover a run with no dispatcher.
58	    console.error("inject_dispatcher_notice: no dispatcher; nothing to do");
59	    return;
60	  }
61	  if (!existsSync(path)) {
62	    // Not an error. The step that calls this runs after a failed or short run
63	    // too, and a session that was never written is a normal outcome there.
64	    console.error(`inject_dispatcher_notice: ${path} does not exist; nothing to do`);
65	    return;
66	  }
67	  const session = JSON.parse(readFileSync(path, "utf8")) as Session;
68	  const messages = session.messages ?? [];
69	  messages.push({
70	    role: "user",
71	    content:
72	      `This run was started by the \`${dispatchedBy}\` agent, which is waiting on your result. ` +
73	      `When you finish, report back to it: end your response with a line holding nothing but ` +
74	      `\`/${dispatchedBy}\`, followed by what you concluded and what it should do next. ` +
75	      `Do not end with a plain comment and no such line -- the agent that started you would ` +
76	      `never be told the work is done.`,
77	  });
78	  session.messages = messages;
79	  writeFileSync(path, JSON.stringify(session, null, 2));
80	  console.error(`inject_dispatcher_notice: appended notice to ${path} (dispatched by ${dispatchedBy})`);

