1	/**
2	 * atoma-launch.ts — the one place that starts atoma, and the only `sudo` between
3	 * the runner and the agent.
4	 *
5	 * Every server atoma starts is a child of this process, so one `sudo -u` here
6	 * puts the credential-holding class on its user; the shell and third-party
7	 * servers are dropped a second time by `run_as_untrusted.sh`, from their own
8	 * entries in the generated tools file. `env` in front rather than
9	 * `--preserve-env`: the latter needs a sudoers permission a self-hosted runner
10	 * may not grant, and both were measured, so the portable one is used. Only what
11	 * a server actually reads is passed; the credentials are not here at all, they
12	 * are in the file atoma deletes.
13	 *
14	 * HOME stays the runner's so the toolchain resolves. It is not writable by
15	 * either tool user, and the caches are redirected by `buildAgentEnv`.
16	 *
17	 * Both invocations of atoma in a run — the first turn, and the second turn a
18	 * stalled run is offered — come through `launchAtoma`, so they cannot drift: the
19	 * argv, the environment, and the redirections are one function. The caller owns
20	 * the files (`--out`, `--logs`) and the budget; this owns the exec.
21	 */
22	import { spawnSync } from "node:child_process";
23	import { appendFileSync, writeFileSync } from "node:fs";
24	import { join } from "node:path";
25	import {
26	  AGENT_DEFINITIONS_DIR,
27	  PROMPT_TEMPLATE,
28	  SKILLS_DIR,
29	  TOOL_USER,
30	} from "../../../domain/machinery/machinery-layout.ts";
31	
32	export interface LaunchOpts {
33	  /** The agent's name — selects the definition file. */
34	  agent: string;
35	  /** The machinery root: `${MACHINERY_ROOT_VAR}`'s value in the caller's environment. */
36	  machineryRoot: string;
37	  toolsFile: string;
38	  credentialsFile: string;
39	  stopFile: string;
40	  /** In-session and out-session are the same file, as the runner has always passed them. */
41	  session: string;
42	  /** Where atoma's stdout lands — this run's report. */
43	  outFile: string;
44	  /** Where atoma's stderr lands — the run log. Appended to on a second turn. */
45	  logsFile: string;
46	  appendLogs: boolean;
47	  budgetSecs: number;
48	  /** The tool server's environment, as `NAME=VALUE` — see `buildAgentEnv`. */
49	  envEntries: string[];
50	}
51	
52	/** One run of atoma. Returns its exit code and writes nothing to stdout. */
53	export function launchAtoma(opts: LaunchOpts): number {
54	  const argv = [
55	    "sudo", "-n", "-u", TOOL_USER, "env", ...opts.envEntries,
56	    "atoma", "run",
57	    "--agent-def", join(opts.machineryRoot, AGENT_DEFINITIONS_DIR, `${opts.agent}.md`),
58	    "--in-session", opts.session,
59	    "--out-session", opts.session,
60	    "--template", join(opts.machineryRoot, PROMPT_TEMPLATE),
61	    "--skills-dir", join(opts.machineryRoot, SKILLS_DIR),
62	    "--max-runtime-secs", String(opts.budgetSecs),
63	    "--stop-file", opts.stopFile,
64	    "--loop-retries",
65	    "--credentials-file", opts.credentialsFile,
66	    "--tools-file", opts.toolsFile,
67	  ];
68	  const run = spawnSync(argv[0]!, argv.slice(1), {
69	    encoding: "buffer",
70	  });
71	  // A spawn that never happened has no exit code, and reading its absence as 0
72	  // would report "atoma succeeded" — the exact lie the inline bash's
73	  // `|| EXIT_CODE=$?` could not tell. The shell's own conventions name the two
74	  // ways an exec can fail (not found, not executable); reuse them so the logs
75	  // read the way the old step's did.
76	  let status = run.status;
77	  if (run.error) {
78	    const code = (run.error as NodeJS.ErrnoException).code === "ENOENT" ? 127 : (run.error as NodeJS.ErrnoException).code === "EACCES" ? 126 : 1;
79	    const line = `${argv[0]}: ${run.error.message}`;
80	    if (opts.appendLogs) appendFileSync(opts.logsFile, `${line}\n`);
81	    else writeFileSync(opts.logsFile, `${line}\n`);
82	    status = code;
83	  } else if (status === null && run.signal === "SIGTERM") {
84	    // Killed rather than exited — the stop watcher's SIGTERM. The shell reports
85	    // 128+n; keep that spelling so the ending classification reads the same
86	    // numbers it always has.
87	    status = 143;
88	  }
89	  writeFileSync(opts.outFile, run.stdout?.toString() ?? "");
90	  if (opts.appendLogs) appendFileSync(opts.logsFile, run.stderr?.toString() ?? "");
91	  else writeFileSync(opts.logsFile, run.stderr?.toString() ?? "");
92	  return status ?? 1;
93	}

